import { NextResponse } from "next/server";
import { roleHasPermission } from "@/modules/shop/auth/session";
import { parseJson, uuidParam } from "@/modules/shop/http";
import { adminRoute } from "@/modules/shop/http-admin";
import { activationStaffSchema } from "@/modules/shop/schemas";
import { processActivation } from "@/modules/shop/services/software-licensing";

export const dynamic = "force-dynamic";

/**
 * Activation processing: start review, assign, request info, edit code, note, approve (with
 * the key generated by the proprietary EXE outside this system) or reject.
 */
export const POST = adminRoute<{ id: string }>("software:activations-process", async (req, { params, staff }) => {
  const { id } = await params;
  const input = await parseJson(req, activationStaffSchema);
  const result = await processActivation(
    { staffId: staff.staff.id, canTransfer: roleHasPermission(staff.staff.role, "players:transfer") },
    uuidParam(id),
    input,
  );
  return NextResponse.json({ ok: true, installationId: result && "id" in result ? result.id : null });
});
